if (d.length * 0.75 > RV().MAX_FOTO) { cv.width = Math.round(cv.width / 2); cv.height = Math.round(cv.height / 2); cv.getContext("2d").drawImage(im, 0, 0, cv.width, cv.height); d = cv.toDataURL("image/jpeg", 0.6); }
