if (c.tipo === "metal" && c.metal && c.metal.kind === "chapa" && c.metal.furos.length) { nP++; av = av.concat(L().conferirChapa(c).avisos.map(function (a) { return a.texto + " — NBR 8800 " + a.item; })); }
