if (!mods.length) { toast("Nenhum módulo de marcenaria no modelo.", "aviso"); return false; }
var alvo = null; mods.forEach(function (f) { if (f.id === id) alvo = f; });
alvo = alvo || this._selecionado() || mods[mods.length - 1];
