self._lerCatalogo(c);
if (k === "nova-chapa") c.chapas.push({ id: "chapa-" + Date.now().toString(36), nome: "Chapa nova 18 mm", tipo: "MDF", espessura: 18, comprimento: 2750, largura: 1850, veio: false, cor: "#dddddd", fita: c.fitas[0] ? c.fitas[0].id : "" });
